-- Corrections are atomic, append-only, and unwind the latest active event first.
-- They post on the original date only after an operator confirms that period is open.
ALTER TABLE loan_billing_event_voids ADD COLUMN period_open_confirmed INTEGER NOT NULL DEFAULT 0 CHECK(period_open_confirmed IN (0,1));
CREATE TRIGGER billing_void_insert_guard BEFORE INSERT ON loan_billing_event_voids BEGIN
 SELECT CASE WHEN NEW.status<>'pending' OR NEW.period_open_confirmed<>1 OR length(trim(NEW.reason))=0 OR NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR NOT EXISTS(SELECT 1 FROM loan_billing_revisions WHERE loan_id=NEW.loan_id AND revision=NEW.expected_revision) THEN RAISE(ABORT,'billing correction stale, unauthorized or period not confirmed open') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.id=NEW.event_id AND e.loan_id=NEW.loan_id AND e.event_date=NEW.effective_date AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final') AND ((e.accrual_journal_id IS NULL AND NEW.accrual_reversal_journal_id IS NULL) OR (e.accrual_journal_id IS NOT NULL AND NEW.accrual_reversal_journal_id IS NOT NULL)) AND ((e.repayment_journal_id IS NULL AND NEW.repayment_reversal_journal_id IS NULL) OR (e.repayment_journal_id IS NOT NULL AND NEW.repayment_reversal_journal_id IS NOT NULL))) THEN RAISE(ABORT,'billing event changed or already reversed') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_billing_events later JOIN loan_billing_events target ON target.id=NEW.event_id WHERE later.loan_id=target.loan_id AND later.rowid>target.rowid AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=later.id AND v.status='final')) THEN RAISE(ABORT,'reverse the latest active billing event first') END;
END;
CREATE TRIGGER billing_void_update_guard BEFORE UPDATE ON loan_billing_event_voids BEGIN
 SELECT CASE WHEN OLD.status<>'pending' OR NEW.status<>'final' OR NEW.id IS NOT OLD.id OR NEW.event_id IS NOT OLD.event_id OR NEW.loan_id IS NOT OLD.loan_id OR NEW.request_key IS NOT OLD.request_key OR NEW.expected_revision IS NOT OLD.expected_revision OR NEW.reason IS NOT OLD.reason OR NEW.created_by IS NOT OLD.created_by OR NEW.effective_date IS NOT OLD.effective_date OR NEW.created_at IS NOT OLD.created_at OR NEW.period_open_confirmed IS NOT OLD.period_open_confirmed OR NEW.accrual_reversal_journal_id IS NOT OLD.accrual_reversal_journal_id OR NEW.repayment_reversal_journal_id IS NOT OLD.repayment_reversal_journal_id THEN RAISE(ABORT,'billing correction immutable') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR NOT EXISTS(SELECT 1 FROM loan_billing_revisions WHERE loan_id=NEW.loan_id AND revision=NEW.expected_revision) THEN RAISE(ABORT,'billing correction stale or unauthorized') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_billing_events later JOIN loan_billing_events target ON target.id=NEW.event_id WHERE later.loan_id=target.loan_id AND later.rowid>target.rowid AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=later.id AND v.status='final')) THEN RAISE(ABORT,'reverse the latest active billing event first') END;
 SELECT CASE WHEN NEW.accrual_reversal_journal_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries j JOIN loan_billing_events e ON e.id=NEW.event_id WHERE j.id=NEW.accrual_reversal_journal_id AND j.status='posted' AND j.reverses_entry_id=e.accrual_journal_id AND j.effective_date=NEW.effective_date AND j.created_by=NEW.created_by) THEN RAISE(ABORT,'accrual reversal incomplete') END;
 SELECT CASE WHEN NEW.repayment_reversal_journal_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries j JOIN loan_billing_events e ON e.id=NEW.event_id WHERE j.id=NEW.repayment_reversal_journal_id AND j.status='posted' AND j.reverses_entry_id=e.repayment_journal_id AND j.effective_date=NEW.effective_date AND j.created_by=NEW.created_by) THEN RAISE(ABORT,'repayment reversal incomplete') END;
END;
CREATE TRIGGER billing_void_final_revision AFTER UPDATE OF status ON loan_billing_event_voids WHEN NEW.status='final' BEGIN UPDATE loan_billing_revisions SET revision=revision+1 WHERE loan_id=NEW.loan_id; END;
CREATE TRIGGER billing_void_no_delete BEFORE DELETE ON loan_billing_event_voids BEGIN SELECT RAISE(ABORT,'billing correction immutable'); END;
DROP TRIGGER billing_reversal_guard;
CREATE TRIGGER billing_reversal_guard BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND NEW.reverses_entry_id IS NOT NULL AND EXISTS(SELECT 1 FROM loan_billing_events WHERE accrual_journal_id=NEW.reverses_entry_id OR repayment_journal_id=NEW.reverses_entry_id) BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v JOIN loan_billing_events e ON e.id=v.event_id WHERE v.status='pending' AND v.created_by=NEW.created_by AND v.effective_date=NEW.effective_date AND NEW.source_type='loan-billing-reversal' AND ((v.accrual_reversal_journal_id=NEW.id AND e.accrual_journal_id=NEW.reverses_entry_id AND NEW.source_id=v.id||':accrual') OR (v.repayment_reversal_journal_id=NEW.id AND e.repayment_journal_id=NEW.reverses_entry_id AND NEW.source_id=v.id||':repayment'))) THEN RAISE(ABORT,'billing reversal requires reviewed correction') END;
END;
